package com.coffeeshop.service;import com.coffeeshop.dto.RefundCommands;import com.coffeeshop.model.RefundModels;import com.coffeeshop.repository.RefundRepository;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class RefundServiceTest{private final Stub repo=new Stub();private final RefundService service=new RefundService(repo);@Test void recordsPartialAndNormalizes(){service.refund(payment("100","20","COMPLETED"),new BigDecimal("30")," Customer return ",null,null,2);assertEquals(new BigDecimal("30.0000"),repo.command.amount());assertEquals("Customer return",repo.command.reason());}@Test void preventsOverRefund(){assertThrows(IllegalArgumentException.class,()->service.refund(payment("100","80","PARTIALLY_REFUNDED"),new BigDecimal("21"),"Reason",null,null,2));}@Test void requiresPositiveAmountAndReason(){assertThrows(IllegalArgumentException.class,()->service.refund(payment("10","0","COMPLETED"),BigDecimal.ZERO,"Reason",null,null,2));assertThrows(IllegalArgumentException.class,()->service.refund(payment("10","0","COMPLETED"),BigDecimal.ONE," ",null,null,2));}@Test void rejectsFinalizedPayment(){assertThrows(IllegalStateException.class,()->service.refund(payment("10","10","REFUNDED"),BigDecimal.ONE,"Reason",null,null,2));}private static RefundModels.Payment payment(String a,String r,String s){return new RefundModels.Payment(1,1,"O1","CARD","Card",new BigDecimal(a),new BigDecimal(r),s,LocalDateTime.now(),new byte[]{1});}private static final class Stub implements RefundRepository{RefundCommands.Create command;public RefundModels.Catalog load(){return new RefundModels.Catalog(List.of(),List.of());}public long refund(RefundCommands.Create q){command=q;return 1;}}}
